SELECT CASE WHEN status IN ('RETURNED', 'CANCELLED') THEN 'priority' ELSE 'other' END AS status_group, status, SUM(CASE WHEN channel = 'store' THEN amount ELSE 0 END) AS store_amount, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(channel))) AS channel_values FROM orders WHERE MONTH(order_date) IN (8, 9, 10) GROUP BY status_group, status HAVING SUM(CASE WHEN channel = 'store' THEN amount ELSE 0 END) > 59 ORDER BY store_amount DESC;
